<body>
    <!-- Header with BlueMind logo -->
    <div class="header">
        <div class="logo">
            <div class="logo-icon"></div>
            <span>BlueMind</span>
        </div>
        <div class="user-info">
            Welcome, <%= currentUser.username %>!
            <form action="/auth/logout" method="GET" style="display: inline;">
                <button class="logout-btn" type="submit">Logout</button>
            </form>
        </div>
    </div>

    <!-- Main content -->
    <div class="container">
        <!-- Sidebar for sending messages -->
        <div class="sidebar">
            <h2 class="sidebar-title">Send New Message</h2>

            <% if (typeof errors !== 'undefined' && errors.length > 0) { %>
                <div class="error-messages">
                    <% errors.forEach(function(error) { %>
                        <div class="error-item"><%= error.msg %></div>
                    <% }); %>
                </div>
            <% } %>

            <form action="/messages/send" method="POST">
                <div class="form-group">
                    <label class="form-label" for="toUserId">To:</label>
                    <select class="form-select" id="toUserId" name="toUserId" required>
                        <option value="">Select a recipient</option>
                        <% users.forEach(function(user) { %>
                            <option value="<%= user.id %>"><%= user.username %></option>
                        <% }); %>
                    </select>
                </div>

                <div class="form-group">
                    <label class="form-label" for="content">Message:</label>
                    <textarea class="form-textarea" id="content" name="content" placeholder="Type your message here..." required></textarea>
                </div>

                <button class="btn-send" type="submit">Send Message</button>
            </form>
        </div>

        <!-- Messages area -->
        <div class="messages-area">
            <h2 class="messages-title">Your Messages</h2>

            <div class="messages-list">
                <% if (messages.length === 0) { %>
                    <div class="no-messages">
                        <p>You have no messages yet.</p>
                        <p>Send a message to another user or wait for someone to message you.</p>
                    </div>
                <% } else { %>
                    <% messages.forEach(function(message) { %>
                        <div class="message">
                            <% 
                                const sender = User.findById(message.fromUserId);
                                const senderName = sender ? sender.username : 'Unknown';
                            %>
                            <div class="message-header">
                                <div class="message-from"><%= senderName %></div>
                                <div class="message-date"><%= new Date(message.createdAt).toLocaleString() %></div>
                            </div>
                            <div class="message-content"><%= message.content %></div>
                        </div>
                    <% }); %>
                <% } %>
            </div>
        </div>
    </div>
</body>
</html>
