            border: 1px solid #ddd;
            border-radius: 4px;
            font-size: 16px;
            transition: border-color 0.3s;
        }

        .form-input:focus {
            outline: none;
            border-color: #0074D9;
        }

        .btn-register {
            background-color: #0074D9; /* Bright blue */
            color: white;
            border: none;
            border-radius: 4px;
            padding: 14px;
