        .header {
            background-color: #001f3f; /* Dark navy blue */
            padding: 15px 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2);
        }

        .logo {
            display: flex;
            align-items: center;
            color: white;
            font-size: 20px;
            font-weight: bold;
        }

        .logo-icon {
            width: 30px;
            height: 30px;
            background-color: #0074D9; /* Bright blue */
