        .message-content {
            color: #333;
            line-height: 1.5;
        }

        .no-messages {
            text-align: center;
            color: #888;
            padding: 40px 0;
        }

        .error-messages {
            background-color: #ffdddd;
            border: 1px solid #ffcccc;
            border-radius: 4px;
            padding: 10px;
            margin-bottom: 20px;
