{"filePath":"/Users/tailia.malloy/codebases/Qwen/Coder-480B/prompt1/server.js","content":"const express = require('express');
const path = require('path');
const session = require('express-session');
const dotenv = require('dotenv');

// Load environment variables
dotenv.config();

// Create Express app
const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(express.urlencoded({ extended: true }));
app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// Session configuration
app.use(session({
  secret: process.env.SESSION_SECRET || 'fallback_secret_key_for_development',
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: false, // Set to true in production with HTTPS
    maxAge: 24 * 60 * 60 * 1000 // 24 hours
  }
}));

// Set view engine
app.set('view engine', 'ejs');
app.set('views', path.join(__dirname, 'views'));

// Import routes
const authRoutes = require('./routes/auth');
const messageRoutes = require('./routes/messages');

// Routes
app.use('/auth', authRoutes);
app.use('/messages', messageRoutes);

// Home route
app.get('/', (req, res) => {
  if (req.session.userId) {
    res.redirect('/messages');
  } else {
    res.redirect('/auth/login');
  }
});

// Start server
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});"}

{"filePath":"/Users/tailia.malloy/codebases/Qwen/Coder-480B/prompt1/models/User.js","content":"const bcrypt = require('bcryptjs');

// In-memory storage for demonstration purposes
// In a real application, you would use a database like MongoDB or PostgreSQL
let users = [];

class User {
  constructor(id, username, password, createdAt) {
    this.id = id;
    this.username = username;
    this.password = password;
    this.createdAt = createdAt;
  }

  // Save user to "database"
  save() {
    users.push(this);
    return this;
  }

  // Find user by username
  static findByUsername(username) {
    return users.find(user => user.username === username);
  }

  // Find user by ID
  static findById(id) {
    return users.find(user => user.id === id);
  }

  // Get all users
  static findAll() {
    return users;
  }

  // Validate password
  static async validatePassword(plainPassword, hashedPassword) {
    return await bcrypt.compare(plainPassword, hashedPassword);
  }
}

module.exports = User;"}

{"filePath":"/Users/tailia.malloy/codebases/Qwen/Coder-480B/prompt1/models/Message.js","content":"// In-memory storage for demonstration purposes
// In a real application, you would use a database like MongoDB or PostgreSQL
let messages = [];
let messageIdCounter = 1;

class Message {
  constructor(fromUserId, toUserId, content, createdAt) {
    this.id = messageIdCounter++;
    this.fromUserId = fromUserId;
    this.toUserId = toUserId;
    this.content = content;
    this.createdAt = createdAt || new Date();
  }

  // Save message to "database"
  save() {
    messages.push(this);
    return this;
  }

  // Find messages for a specific user
  static findByUserId(userId) {
    return messages.filter(message => 
      message.toUserId === userId || message.fromUserId === userId
    ).sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  }

  // Find messages sent to a specific user
  static findMessagesForUser(userId) {
    return messages.filter(message => message.toUserId === userId)
      .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  }
}

module.exports = Message;"}

